// Upstream CSS, line for line, with component-prefixed parts (data-slot),
// keyframes (blocks-*) and colors (--blocks-*). React 19 hoists this <style>
// into <head> once, however many instances render.
const css = `
[data-slot="blocks-stack"] {
  display: grid;
  justify-items: center;
}
[data-slot="blocks-stack"]:dir(rtl) {
  scale: -1 1;
}

[data-slot="blocks-large-ball"] {
  position: relative;
  width: 65px;
  aspect-ratio: 1;
  border-radius: 50%;
  background: linear-gradient(to top, var(--blocks-shape, #aaa) 0 50%, var(--blocks-shade, #777) 0);
  animation:
    blocks-large-ball-1 0.7s ease-in-out 0s both,
    blocks-large-ball-2 1.2s ease-in-out 0.7s forwards;
}
@keyframes blocks-large-ball-1 {
  from {
    transform: translateX(0);
  }
  to {
    transform: translate(50%, 3%) rotate(30deg);
  }
}
@keyframes blocks-large-ball-2 {
  from {
    transform: translate(50%, 3%) rotate(30deg);
  }
  50% {
    transform: translate(-50%, 3%) rotate(-35deg);
  }
  75% {
    transform: translate(10%, 1%) rotate(10deg);
  }
  to {
    transform: translateX(0);
  }
}

[data-slot="blocks-bar"] {
  width: 120px;
  height: 12px;
  border-radius: 999px;
  background-color: var(--blocks-shape, #aaa);
  animation:
    blocks-bar-1 0.6s ease-in-out 0s both,
    blocks-bar-2 1.2s ease-in-out 0.6s forwards;
}
@keyframes blocks-bar-1 {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(8%) rotate(6deg);
  }
}
@keyframes blocks-bar-2 {
  from {
    transform: translateX(8%) rotate(6deg);
  }
  50% {
    transform: translateX(-8%) rotate(-6deg);
  }
  75% {
    transform: translateX(2%) rotate(2deg);
  }
  to {
    transform: translateX(0);
  }
}

[data-slot="blocks-small-ball"] {
  position: relative;
  width: 35px;
  aspect-ratio: 1;
  border-radius: 50%;
  background: linear-gradient(to top right, var(--blocks-shape, #aaa) 0 50%, var(--blocks-shade, #777) 0);
  animation:
    blocks-small-ball-1 0.5s ease-in-out 0s both,
    blocks-small-ball-2 1.2s ease-in-out 0.5s forwards;
}
@keyframes blocks-small-ball-1 {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(30%) rotate(25deg);
  }
}
@keyframes blocks-small-ball-2 {
  from {
    transform: translateX(30%) rotate(25deg);
  }
  50% {
    transform: translateX(-30%) rotate(-25deg);
  }
  75% {
    transform: translateX(10%) rotate(5deg);
  }
  to {
    transform: translateX(0);
  }
}

/* Reduced motion: no motion; the stack shows its resting state. */
@media (prefers-reduced-motion: reduce) {
  [data-slot="blocks-large-ball"],
  [data-slot="blocks-bar"],
  [data-slot="blocks-small-ball"] {
    animation: none;
  }
}
`;

/**
 * A ball, a bar and a smaller ball stacked like toy blocks, wobbling into
 * balance once on mount. Remount it (change its `key`) to play it again.
 */
function Blocks({ className, ...props }: React.ComponentProps<"div">) {
  const labelled =
    props["aria-label"] !== undefined || props["aria-labelledby"] !== undefined;
  return (
    <div
      data-slot="blocks"
      role={labelled ? "img" : undefined}
      aria-hidden={labelled ? undefined : true}
      className={cn(
        "relative grid aspect-square w-full max-w-80 place-content-center overflow-hidden bg-[var(--blocks-surface,#fff)]",
        className,
      )}
      {...props}
    >
      <style href="designfrom-blocks" precedence="default">
        {css}
      </style>
      <div data-slot="blocks-stack">
        <div data-slot="blocks-large-ball" />
        <div data-slot="blocks-bar" />
        <div data-slot="blocks-small-ball" />
      </div>
    </div>
  );
}

export { Blocks };
